import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { 
  FaMoon, FaSun, FaVolumeUp, FaVolumeMute, 
  FaCloudRain, FaWater, FaTree, FaFire, 
  FaHeadphones, FaBell, FaClock, FaHeartbeat,
  FaPlay, FaPause, FaStop, FaArrowLeft, FaStar
} from 'react-icons/fa';

function SleepMode() {
  const navigate = useNavigate();
  const [selectedSound, setSelectedSound] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState(50);
  const [isMuted, setIsMuted] = useState(false);
  const [timerMinutes, setTimerMinutes] = useState(30);
  const [timeLeft, setTimeLeft] = useState(null);
  const [breathPhase, setBreathPhase] = useState('inhale');
  const [breathCount, setBreathCount] = useState(0);
  const [isBreathing, setIsBreathing] = useState(false);
  const [darkMode, setDarkMode] = useState(true);
  const [showStars, setShowStars] = useState(true);
  const audioRef = useRef(null);

  // Working sound URLs (free and reliable)
  const sounds = [
    { id: 'rain', name: 'Gentle Rain', icon: <FaCloudRain size={24} />, color: '#4a90e2', url: 'https://actions.google.com/soundbar/audio/rain.mp3' },
    { id: 'ocean', name: 'Ocean Waves', icon: <FaWater size={24} />, color: '#2ecc71', url: 'https://actions.google.com/soundbar/audio/ocean.mp3' },
    { id: 'forest', name: 'Forest Birds', icon: <FaTree size={24} />, color: '#27ae60', url: 'https://actions.google.com/soundbar/audio/birds.mp3' },
    { id: 'fireplace', name: 'Fireplace', icon: <FaFire size={24} />, color: '#e67e22', url: 'https://actions.google.com/soundbar/audio/fireplace.mp3' },
    { id: 'lofi', name: 'Lo-fi Sleep', icon: <FaHeadphones size={24} />, color: '#9b59b6', url: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3' },
  ];

  // Breathing sequence
  useEffect(() => {
    let interval;
    if (isBreathing) {
      interval = setInterval(() => {
        setBreathPhase(prev => {
          if (prev === 'inhale') return 'hold';
          if (prev === 'hold') return 'exhale';
          if (prev === 'exhale') {
            setBreathCount(c => c + 1);
            return 'inhale';
          }
          return 'inhale';
        });
      }, 4000);
    }
    return () => clearInterval(interval);
  }, [isBreathing]);

  // Sleep timer
  useEffect(() => {
    let timer;
    if (timeLeft !== null && timeLeft > 0) {
      timer = setTimeout(() => setTimeLeft(timeLeft - 1), 60000);
    } else if (timeLeft === 0) {
      if (audioRef.current) {
        audioRef.current.pause();
        setIsPlaying(false);
      }
      setIsBreathing(false);
      alert('✨ Sleep mode completed. Goodnight! ✨');
    }
    return () => clearTimeout(timer);
  }, [timeLeft]);

  const playSound = (sound) => {
    // Stop current sound if playing
    if (audioRef.current) {
      audioRef.current.pause();
    }
    
    setSelectedSound(sound);
    const audio = new Audio(sound.url);
    audio.loop = true;
    audio.volume = volume / 100;
    audio.play().catch(error => {
      console.error('Audio play error:', error);
      // Fallback sound
      const fallbackAudio = new Audio('https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3');
      fallbackAudio.loop = true;
      fallbackAudio.volume = volume / 100;
      fallbackAudio.play();
      audioRef.current = fallbackAudio;
    });
    audioRef.current = audio;
    setIsPlaying(true);
    setIsBreathing(true);
  };

  const pauseSound = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      setIsPlaying(false);
      setIsBreathing(false);
    }
  };

  const resumeSound = () => {
    if (audioRef.current && selectedSound) {
      audioRef.current.play();
      setIsPlaying(true);
      setIsBreathing(true);
    }
  };

  const stopSound = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current = null;
    }
    setSelectedSound(null);
    setIsPlaying(false);
    setIsBreathing(false);
    setBreathPhase('inhale');
    setBreathCount(0);
    setTimeLeft(null);
  };

  const adjustVolume = (newVolume) => {
    setVolume(newVolume);
    if (audioRef.current) {
      audioRef.current.volume = newVolume / 100;
    }
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (audioRef.current) {
      audioRef.current.volume = isMuted ? volume / 100 : 0;
    }
  };

  const startSleepTimer = () => setTimeLeft(timerMinutes);
  const cancelTimer = () => setTimeLeft(null);

  const getBreathText = () => {
    if (breathPhase === 'inhale') return 'Breathe In... 🌬️';
    if (breathPhase === 'hold') return 'Hold... ⏸️';
    return 'Breathe Out... 💨';
  };

  const stars = [...Array(80)].map((_, i) => ({
    id: i,
    left: Math.random() * 100,
    top: Math.random() * 100,
    size: Math.random() * 2.5 + 1,
    delay: Math.random() * 5
  }));

  return (
    <div style={{...styles.container, background: darkMode ? 'linear-gradient(135deg, #0a0a2a 0%, #1a1a3a 100%)' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'}}>
      <Navbar />
      <div style={styles.navSpacer} />
      
      {/* Animated Stars */}
      {showStars && (
        <div style={styles.starsContainer}>
          {stars.map(star => (
            <div
              key={star.id}
              style={{
                ...styles.star,
                left: `${star.left}%`,
                top: `${star.top}%`,
                width: `${star.size}px`,
                height: `${star.size}px`,
                animationDelay: `${star.delay}s`
              }}
            />
          ))}
        </div>
      )}

      <div style={styles.content}>
        <button onClick={() => navigate('/dashboard')} style={styles.backBtn}>
          <FaArrowLeft size={12} /> Back to Home
        </button>

        {/* Main Sleep Mode Card */}
        <div style={styles.sleepCard}>
          <div style={styles.sleepHeader}>
            <FaMoon size={28} color="#f1c40f" />
            <h1 style={styles.sleepTitle}>Sleep & Calm Mode</h1>
            <button onClick={() => setDarkMode(!darkMode)} style={styles.themeBtn}>
              {darkMode ? <FaSun size={16} /> : <FaMoon size={16} />}
            </button>
          </div>
          <p style={styles.sleepSubtitle}>Find your peace, drift into tranquility</p>

          {/* Breathing Orb */}
          <div style={styles.breathingContainer}>
            <div style={{...styles.breathingOrb, transform: `scale(${breathPhase === 'inhale' ? 1.3 : breathPhase === 'exhale' ? 0.8 : 1.1})`, transition: 'transform 4s ease-in-out'}}>
              <div style={styles.orbInner}>
                <FaHeartbeat size={40} color="#fff" />
              </div>
            </div>
            <div style={styles.breathText}>{getBreathText()}</div>
            <div style={styles.breathCount}>Breaths: {breathCount}</div>
            <button onClick={() => setIsBreathing(!isBreathing)} style={styles.breathToggle}>
              {isBreathing ? 'Pause' : 'Start'} Breathing
            </button>
          </div>

          {/* Sound Library */}
          <div style={styles.soundSection}>
            <h3 style={styles.sectionTitle}>🎵 Calming Sounds</h3>
            <div style={styles.soundGrid}>
              {sounds.map(sound => (
                <div
                  key={sound.id}
                  style={{...styles.soundCard, background: selectedSound?.id === sound.id ? `${sound.color}20` : 'rgba(255,255,255,0.1)', borderColor: selectedSound?.id === sound.id ? sound.color : 'rgba(255,255,255,0.2)'}}
                  onClick={() => playSound(sound)}
                >
                  <div style={{...styles.soundIcon, color: sound.color}}>{sound.icon}</div>
                  <div style={styles.soundName}>{sound.name}</div>
                  {selectedSound?.id === sound.id && isPlaying && (
                    <div style={styles.playingIndicator}>
                      <div style={styles.wave}></div>
                      <div style={styles.wave}></div>
                      <div style={styles.wave}></div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* Playback Controls */}
          {selectedSound && (
            <div style={styles.volumeControl}>
              <button onClick={toggleMute} style={styles.muteBtn}>
                {isMuted ? <FaVolumeMute size={18} /> : <FaVolumeUp size={18} />}
              </button>
              <input
                type="range"
                min="0"
                max="100"
                value={volume}
                onChange={(e) => adjustVolume(e.target.value)}
                style={styles.volumeSlider}
              />
              <span style={styles.volumeValue}>{volume}%</span>
              {isPlaying ? (
                <button onClick={pauseSound} style={styles.playPauseBtn}>
                  <FaPause size={12} /> Pause
                </button>
              ) : (
                <button onClick={resumeSound} style={styles.playPauseBtn}>
                  <FaPlay size={12} /> Play
                </button>
              )}
              <button onClick={stopSound} style={styles.stopBtn}>
                <FaStop size={12} /> Stop
              </button>
            </div>
          )}

          {/* Sleep Timer */}
          <div style={styles.timerSection}>
            <h3 style={styles.sectionTitle}>⏰ Sleep Timer</h3>
            <div style={styles.timerControls}>
              {[15, 30, 45, 60].map(mins => (
                <button
                  key={mins}
                  onClick={() => setTimerMinutes(mins)}
                  style={{...styles.timerBtn, background: timerMinutes === mins ? '#667eea' : 'rgba(255,255,255,0.1)'}}
                >
                  {mins} min
                </button>
              ))}
            </div>
            {timeLeft !== null ? (
              <div style={styles.activeTimer}>
                <FaClock size={16} />
                <span>Time left: {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                <button onClick={cancelTimer} style={styles.cancelTimerBtn}>Cancel</button>
              </div>
            ) : (
              <button onClick={startSleepTimer} style={styles.startTimerBtn}>
                Start {timerMinutes} min Timer
              </button>
            )}
          </div>

          {/* Bedtime Reminder */}
          <div style={styles.reminderCard}>
            <FaBell size={14} color="#f1c40f" />
            <span>Set a bedtime reminder to build a healthy sleep routine</span>
            <button 
              onClick={() => {
                const reminderTime = prompt("Set bedtime reminder (e.g., 10:30 PM):");
                if (reminderTime) {
                  alert(`Reminder set for ${reminderTime}. We'll remind you to wind down! 💙`);
                  localStorage.setItem('bedtimeReminder', reminderTime);
                }
              }} 
              style={styles.reminderBtn}
            >
              Set Reminder
            </button>
          </div>
        </div>

        {/* Daily Affirmation */}
        <div style={styles.affirmationCard}>
          <FaStar size={16} color="#f1c40f" />
          <p style={styles.affirmationText}>
            "You have done enough today. Rest is not a reward, it's a necessity. Let go of what you cannot control and sink into the peace of this moment."
          </p>
        </div>
      </div>
    </div>
  );
}

